PRAGMA defer_foreign_keys=ON;
CREATE TABLE family_booking_roots(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),request_id TEXT NOT NULL REFERENCES family_request_roots(id),booking_id TEXT NOT NULL REFERENCES schedule_bookings(id),serial INTEGER NOT NULL CHECK(serial>0),record_number TEXT NOT NULL,first_version_id TEXT NOT NULL UNIQUE REFERENCES family_booking_versions(id) DEFERRABLE INITIALLY DEFERRED,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,serial),UNIQUE(store_id,record_number),FOREIGN KEY(first_version_id,id) REFERENCES family_booking_versions(id,root_id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE family_booking_versions(id TEXT PRIMARY KEY,root_id TEXT NOT NULL REFERENCES family_booking_roots(id),store_id TEXT NOT NULL REFERENCES stores(id),version INTEGER NOT NULL CHECK(version>0),base_sequence INTEGER NOT NULL CHECK(base_sequence>=0),event_id TEXT NOT NULL UNIQUE REFERENCES family_booking_events(id) DEFERRABLE INITIALLY DEFERRED,schedule_prefix INTEGER NOT NULL CHECK(schedule_prefix>0),request_prefix INTEGER NOT NULL CHECK(request_prefix>0),booking_snapshot_json TEXT NOT NULL CHECK(json_valid(booking_snapshot_json)),request_snapshot_json TEXT NOT NULL CHECK(json_valid(request_snapshot_json)),public_note TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(root_id,version),UNIQUE(id,root_id),FOREIGN KEY(event_id,id) REFERENCES family_booking_events(id,version_id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE family_booking_events(id TEXT PRIMARY KEY,root_id TEXT NOT NULL REFERENCES family_booking_roots(id),version_id TEXT NOT NULL REFERENCES family_booking_versions(id),store_id TEXT NOT NULL REFERENCES stores(id),revision INTEGER NOT NULL CHECK(revision>0),sequence INTEGER NOT NULL CHECK(sequence>0),action TEXT NOT NULL CHECK(action IN('publish','withdraw')),status TEXT NOT NULL CHECK(status IN('published','withdrawn')),reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(root_id,revision),UNIQUE(store_id,sequence),UNIQUE(id,version_id));
CREATE VIEW family_booking_current AS SELECT e.* FROM family_booking_events e WHERE e.revision=(SELECT max(revision) FROM family_booking_events WHERE root_id=e.root_id);
CREATE VIEW family_booking_sources AS SELECT b.id booking_id,b.booking_number,b.customer_id,b.store_id,b.plan_id,b.plan_version,b.cycle_id,b.cycle_version,e.id event_id,e.revision,e.sequence,e.action,e.status,e.slot_id,e.slot_revision,s.starts_at,s.ends_at,e.created_at recorded_at FROM schedule_bookings b JOIN schedule_booking_events e ON e.booking_id=b.id JOIN schedule_slot_events s ON s.slot_id=e.slot_id AND s.revision=e.slot_revision WHERE e.revision=(SELECT max(revision) FROM schedule_booking_events WHERE booking_id=b.id);
CREATE TRIGGER family_booking_root_source BEFORE INSERT ON family_booking_roots BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM family_request_roots q JOIN schedule_bookings b ON b.id=NEW.booking_id JOIN users u ON u.id=q.recipient_id JOIN guardian_links g ON g.user_id=u.id AND g.customer_id=q.customer_id LEFT JOIN user_security s ON s.user_id=u.id WHERE q.id=NEW.request_id AND q.store_id=NEW.store_id AND q.customer_id=b.customer_id AND q.store_id=b.store_id AND q.created_at<=NEW.created_at AND b.created_at<=NEW.created_at AND g.active=1 AND u.active=1 AND u.role='guardian' AND coalesce(s.must_change_password,0)=0) OR NEW.serial<>coalesce((SELECT max(serial)+1 FROM family_booking_roots WHERE store_id=NEW.store_id),1) OR NEW.record_number IS NOT 'FB-'||replace(substr(NEW.created_at,1,10),'-','')||'-'||printf('%05d',NEW.serial) THEN RAISE(ABORT,'family actual booking fixed request/customer/original source') END;END;
CREATE TRIGGER family_booking_version_source BEFORE INSERT ON family_booking_versions BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM family_booking_roots r JOIN family_request_roots q ON q.id=r.request_id JOIN family_request_current c ON c.root_id=q.id JOIN family_booking_sources m ON m.booking_id=r.booking_id WHERE r.id=NEW.root_id AND r.store_id=NEW.store_id AND q.customer_id=m.customer_id AND q.store_id=m.store_id AND NEW.booking_snapshot_json=json_object('booking_id',m.booking_id,'booking_number',m.booking_number,'customer_id',m.customer_id,'store_id',m.store_id,'plan_id',m.plan_id,'plan_version',m.plan_version,'cycle_id',m.cycle_id,'cycle_version',m.cycle_version,'event_id',m.event_id,'revision',m.revision,'sequence',m.sequence,'action',m.action,'status',m.status,'slot_id',m.slot_id,'slot_revision',m.slot_revision,'starts_at',m.starts_at,'ends_at',m.ends_at,'recorded_at',m.recorded_at) AND NEW.request_snapshot_json=json_object('request_id',q.id,'customer_id',q.customer_id,'recipient_id',q.recipient_id,'request_kind',q.request_kind,'event_id',c.id,'revision',c.revision,'sequence',c.sequence,'status',c.status) AND NEW.schedule_prefix=(SELECT max(sequence) FROM schedule_journal WHERE store_id=r.store_id) AND NEW.request_prefix=(SELECT max(sequence) FROM family_request_events WHERE store_id=r.store_id) AND EXISTS(SELECT 1 FROM family_request_roots q JOIN users u ON u.id=q.recipient_id JOIN guardian_links g ON g.customer_id=q.customer_id AND g.user_id=u.id LEFT JOIN user_security s ON s.user_id=u.id WHERE q.id=r.request_id AND u.active=1 AND u.role='guardian' AND g.active=1 AND coalesce(s.must_change_password,0)=0)) OR EXISTS(SELECT 1 FROM schedule_journal WHERE store_id=NEW.store_id AND sequence<=NEW.schedule_prefix AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM family_request_events WHERE store_id=NEW.store_id AND sequence<=NEW.request_prefix AND created_at>NEW.created_at) OR NEW.version<>coalesce((SELECT max(version)+1 FROM family_booking_versions WHERE root_id=NEW.root_id),1) OR NEW.base_sequence<>coalesce((SELECT max(sequence) FROM family_booking_events WHERE store_id=NEW.store_id),0) OR NEW.version=1 AND NOT EXISTS(SELECT 1 FROM family_booking_roots r WHERE r.id=NEW.root_id AND r.first_version_id=NEW.id AND r.created_at=NEW.created_at AND r.created_by=NEW.created_by) THEN RAISE(ABORT,'family actual booking current source/prefix/version') END;END;
CREATE TRIGGER family_booking_event_source BEFORE INSERT ON family_booking_events BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM family_booking_versions v WHERE v.id=NEW.version_id AND v.root_id=NEW.root_id AND v.store_id=NEW.store_id) OR NEW.revision<>coalesce((SELECT max(revision)+1 FROM family_booking_events WHERE root_id=NEW.root_id),1) OR NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM family_booking_events WHERE store_id=NEW.store_id),1) OR NEW.action='publish' AND (NEW.status<>'published' OR NOT EXISTS(SELECT 1 FROM family_booking_versions v WHERE v.id=NEW.version_id AND v.event_id=NEW.id AND v.created_at=NEW.created_at AND v.created_by=NEW.created_by AND v.reason=NEW.reason AND v.base_sequence+1=NEW.sequence AND v.version=coalesce((SELECT max(v2.version)+1 FROM family_booking_events e JOIN family_booking_versions v2 ON v2.id=e.version_id WHERE e.root_id=NEW.root_id),1) AND EXISTS(SELECT 1 FROM family_booking_roots r JOIN family_request_roots q ON q.id=r.request_id JOIN family_request_current c ON c.root_id=q.id JOIN family_booking_sources m ON m.booking_id=r.booking_id WHERE r.id=v.root_id AND r.store_id=v.store_id AND q.customer_id=m.customer_id AND q.store_id=m.store_id AND v.booking_snapshot_json=json_object('booking_id',m.booking_id,'booking_number',m.booking_number,'customer_id',m.customer_id,'store_id',m.store_id,'plan_id',m.plan_id,'plan_version',m.plan_version,'cycle_id',m.cycle_id,'cycle_version',m.cycle_version,'event_id',m.event_id,'revision',m.revision,'sequence',m.sequence,'action',m.action,'status',m.status,'slot_id',m.slot_id,'slot_revision',m.slot_revision,'starts_at',m.starts_at,'ends_at',m.ends_at,'recorded_at',m.recorded_at) AND v.request_snapshot_json=json_object('request_id',q.id,'customer_id',q.customer_id,'recipient_id',q.recipient_id,'request_kind',q.request_kind,'event_id',c.id,'revision',c.revision,'sequence',c.sequence,'status',c.status) AND v.schedule_prefix=(SELECT max(sequence) FROM schedule_journal WHERE store_id=r.store_id) AND v.request_prefix=(SELECT max(sequence) FROM family_request_events WHERE store_id=r.store_id) AND EXISTS(SELECT 1 FROM family_request_roots q JOIN users u ON u.id=q.recipient_id JOIN guardian_links g ON g.customer_id=q.customer_id AND g.user_id=u.id LEFT JOIN user_security s ON s.user_id=u.id WHERE q.id=r.request_id AND u.active=1 AND u.role='guardian' AND g.active=1 AND coalesce(s.must_change_password,0)=0)))) OR NEW.action='withdraw' AND (NEW.status<>'withdrawn' OR NOT EXISTS(SELECT 1 FROM family_booking_current c WHERE c.root_id=NEW.root_id AND c.version_id=NEW.version_id AND c.status='published')) THEN RAISE(ABORT,'family actual booking complete paired source/event') END;END;
CREATE TRIGGER family_booking_roots_actor BEFORE INSERT ON family_booking_roots WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.role IN('manager','reception') AND u.active=1 AND coalesce(s.must_change_password,0)=0) OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM family_booking_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'family actual booking current staff/time');END;
CREATE TRIGGER family_booking_roots_no_update BEFORE UPDATE ON family_booking_roots BEGIN SELECT RAISE(ABORT,'family actual booking immutable');END;
CREATE TRIGGER family_booking_roots_no_delete BEFORE DELETE ON family_booking_roots BEGIN SELECT RAISE(ABORT,'family actual booking immutable');END;
CREATE TRIGGER family_booking_versions_actor BEFORE INSERT ON family_booking_versions WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.role IN('manager','reception') AND u.active=1 AND coalesce(s.must_change_password,0)=0) OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM family_booking_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'family actual booking current staff/time');END;
CREATE TRIGGER family_booking_versions_no_update BEFORE UPDATE ON family_booking_versions BEGIN SELECT RAISE(ABORT,'family actual booking immutable');END;
CREATE TRIGGER family_booking_versions_no_delete BEFORE DELETE ON family_booking_versions BEGIN SELECT RAISE(ABORT,'family actual booking immutable');END;
CREATE TRIGGER family_booking_versions_text BEFORE INSERT ON family_booking_versions WHEN length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300 OR instr(NEW.reason,char(0))>0 OR length(trim(NEW.public_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.public_note)>2000 OR instr(NEW.public_note,char(0))>0 BEGIN SELECT RAISE(ABORT,'family actual booking explicit public note/internal basis');END;
CREATE TRIGGER family_booking_events_actor BEFORE INSERT ON family_booking_events WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.role IN('manager','reception') AND u.active=1 AND coalesce(s.must_change_password,0)=0) OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM family_booking_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'family actual booking current staff/time');END;
CREATE TRIGGER family_booking_events_no_update BEFORE UPDATE ON family_booking_events BEGIN SELECT RAISE(ABORT,'family actual booking immutable');END;
CREATE TRIGGER family_booking_events_no_delete BEFORE DELETE ON family_booking_events BEGIN SELECT RAISE(ABORT,'family actual booking immutable');END;
CREATE TRIGGER family_booking_events_text BEFORE INSERT ON family_booking_events WHEN length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300 OR instr(NEW.reason,char(0))>0 BEGIN SELECT RAISE(ABORT,'family actual booking explicit public note/internal basis');END;
